'use strict';

const fs = require('fs');
const input = fs.readFileSync(0, 'utf8').trim().split(/\s+/).map(Number);

const n = input[0];
const heights = input.slice(1);
const indices = Array.from({ length: n }, (_, i) => i);

indices.sort((a, b) => heights[b] - heights[a]);

const active = new Uint8Array(n);
let components = 0;
let best = 0;

for (let i = 0; i < n;) {
  let j = i;
  while (j < n && heights[indices[j]] === heights[indices[i]]) j++;

  for (let k = i; k < j; k++) {
    const pos = indices[k];
    const left = pos > 0 && active[pos - 1];
    const right = pos + 1 < n && active[pos + 1];

    if (!left && !right) components++;
    else if (left && right) components--;

    active[pos] = 1;
  }

  best = Math.max(best, components);
  i = j;
}

console.log(best + 1);
